\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$ begin begin execute command;exception when others then raise notice 'PASS denied: %',label;return;end;raise exception 'FAIL allowed: %',label;end $$;
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into moderators values('00000000-0000-0000-0000-000000000003');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
with made as (insert into observations(author_id,category,title,description,latitude,longitude,taxonomy_version,domain_id,topic_id,event_type_id,answers) values(auth.uid(),'Travel','Synthetic correction','',61.22,-149.9,2,'travel','travel.surface','black_ice','{}') returning id) select set_config('test.id',(select id::text from made),true);
select correct_observation(current_setting('test.id')::uuid,'Corrected note','{"visibility":"reduced"}');
select pg_temp.assert_true((select description='Corrected note' and answers->>'visibility'='reduced' and status='published' and verification='unverified' and expires_at=observed_at+interval '24 hours' from observations where id=current_setting('test.id')::uuid),'owner can correct notes/details without extending expiry');
select pg_temp.denied($q$update observations set title='Changed identity' where id=current_setting('test.id')::uuid$q$,'direct update cannot change identity');
select pg_temp.denied($q$update observations set observed_at=now()+interval '1 day' where id=current_setting('test.id')::uuid$q$,'cannot extend window with a new observed time');
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'Note','{"animal":"bear"}')$q$,'catalog validation still rejects unrelated answers');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'Someone else','{}')$q$,'other author cannot correct');
select respond_to_observation(current_setting('test.id')::uuid,'observed',now());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'After response','{}')$q$,'community response locks corrections');
reset role;
delete from observation_responses;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
update observations set created_at=clock_timestamp()-interval '10 minutes' where id=current_setting('test.id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'Too late','{}')$q$,'server deadline enforced');
select pg_temp.denied($q$update observations set description='Bypass' where id=current_setting('test.id')::uuid$q$,'direct REST update cannot bypass deadline');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
update observations set created_at=clock_timestamp()+interval '1 minute' where id=current_setting('test.id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'Future clock','{}')$q$,'future timestamps fail closed');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
update observations set created_at=clock_timestamp(),verification='reviewed' where id=current_setting('test.id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'Reviewed edit','{}')$q$,'reviewed observation stays locked');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select review_observation(current_setting('test.id')::uuid,'hide','unverified','Synthetic moderation',false,'none','none','not_assessed','none');
select pg_temp.assert_true((select status='hidden' from observations where id=current_setting('test.id')::uuid),'moderation RPC remains available');
set local role anon;
select pg_temp.denied($q$select correct_observation(current_setting('test.id')::uuid,'Anonymous','{}')$q$,'anonymous correction denied');
rollback;
